def extend_diagonals(grid):
    """Extend every same-color diagonal pair along its diagonal away from each other, painting background cells to the edge or until a non-background cell."""
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            for dr,dc in ((1,1),(1,-1)):
                r2,c2=r+dr,c+dc
                if 0<=r2<h and 0<=c2<w and grid[r][c]==grid[r2][c2]!=bg:
                    col=grid[r][c]
                    for sr,sc,rr,cc in ((dr,dc,r2,c2),(-dr,-dc,r,c)):
                        while True:
                            rr,cc=rr+sr,cc+sc
                            if not(0<=rr<h and 0<=cc<w) or grid[rr][cc]!=bg: break
                            out[rr][cc]=col
    return out

